11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () =>
55	        answerInTurn(ws, session, orchestrator, sessionStore, validation, signal)
56	      );
57	    }
58	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
59	    return wsErrorHandler(ws, async () => answerFrame(ws, session, sessionStore, validation));
60	  };
61	}
62	
63	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
64	async function answerInTurn(
65	  ws: WebSocket,
66	  session: ChatSession,
67	  orchestrator: ChatOrchestrator,
68	  sessionStore: SessionStore | undefined,
69	  validation: ValidationResult,
70	  signal: AbortSignal | undefined
71	): Promise<void> {
72	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
73	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
74	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
75	    return;
76	  }
77	  const startedAt = Date.now();
78	  try {
79	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
80	  } finally {
81	    endTurn(ws, session, signal, startedAt);
82	  }
83	}
84	
85	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
86	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
87	  if (signal?.aborted) {
88	    log.info('message', 'turn abandoned: its socket closed', {
89	      sessionId: session.sessionId,
90	      elapsedMs: Date.now() - startedAt,
91	    });
92	    return;
93	  }
94	  sendStreamEnd(ws);
95	}
96	
97	async function answerUserMessage(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  orchestrator: ChatOrchestrator,
101	  sessionStore: SessionStore | undefined,
102	  validation: ValidationResult,
103	  signal: AbortSignal | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  await answerFrame(ws, session, sessionStore, validation);
108	}
109	
110	async function answerFrame(
111	  ws: WebSocket,
112	  session: ChatSession,
113	  sessionStore: SessionStore | undefined,
114	  validation: ValidationResult
115	): Promise<void> {
116	  if (!validation.valid) {
117	    log.warn('message', 'validation failed', {error: validation.error});
118	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
119	    return;
120	  }
121	
122	  const message = validation.data;
123	  if (message.type === 'ping') handlePing(ws, message.timestamp);
124	  if (message.type === 'list_sessions') await answerSessionList(ws, session, sessionStore, message);
125	}
126	
127	// Answered beside ping, off the session lock: a history request is not a turn, so it never queues behind a stream.
128	async function answerSessionList(
129	  ws: WebSocket,
130	  session: ChatSession,
131	  sessionStore: SessionStore | undefined,
132	  message: ListSessionsMessage
133	): Promise<void> {
134	  try {
135	    const summaries =
136	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
137	    sendSessionList(ws, summaries);
138	  } catch (error) {
139	    const detail = error instanceof Error ? error.message : 'Unknown error';
140	    log.error('ws', 'session list failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
141	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
142	  }
143	}
144	
145	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
146	function isUserMessageFrame(rawMessage: unknown): boolean {
147	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
148	}
149	
150	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
151	  try {
152	    await action();
153	  } catch (error) {
154	    const message = error instanceof Error ? error.message : 'Unknown error';
155	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
156	    log.error('message', 'handling error', {error: message, code});
157	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
158	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
159	      return;
160	    }
161	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
162	  }
163	}
164	
165	async function handleUserMessage(
166	  ws: WebSocket,
167	  session: ChatSession,
168	  orchestrator: ChatOrchestrator,
169	  content: string,
170	  signal: AbortSignal | undefined
171	): Promise<void> {
172	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
173	
174	  const userEntry = createUserEntry(content);
175	  const userIndex = appendEntry(session, userEntry);
176	  sendUpsert(ws, userIndex, userEntry);
177	
178	  const parser = new ThinkingTagParser();
179	  const state: StreamState = {
180	    thinkingIndex: null,
181	    assistantIndex: null,
182	    suppressOutput: false,
183	    sentAssistantIndices: [],
184	  };
185	
186	  let textChunkCount = 0;
187	
188	  try {
189	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
190	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
191	      if (signal?.aborted) break;
192	      textChunkCount = logChunk(chunk, textChunkCount);
193	      processChunk(ws, session, state, parser, chunk);
194	    }
195	  } finally {
196	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
197	    flushHeldText(ws, session, state, parser);
198	    closeCutOff(ws, session, state, 'thinkingIndex');
199	    closeCutOff(ws, session, state, 'assistantIndex');
200	  }
201	
202	  if (textChunkCount > 0) {
203	    log.debug('stream', `received ${textChunkCount} text chunks`);
204	  }
205	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
206	}
207	
208	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
209	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
210	  if (chunk.type === 'text') return textChunkCount + 1;
211	
212	  if (textChunkCount > 0) {
213	    log.debug('stream', `received ${textChunkCount} text chunks`);
214	  }
215	
216	  if (chunk.type === 'tool_result') {
217	    log.debug('stream', 'tool_result chunk', {
218	      messageCount: chunk.clientMessages.length,
219	      types: chunk.clientMessages.map(m => m.type),
220	    });
221	    return 0;
222	  }
223	
224	  log.debug('stream', 'chunk', {type: chunk.type});
225	  return 0;
226	}
227	
228	function processChunk(
229	  ws: WebSocket,
230	  session: ChatSession,
231	  state: StreamState,
232	  parser: ThinkingTagParser,
233	  chunk: MessageChunk
234	): void {
235	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
236	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
237	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
238	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
239	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
240	}
241	
242	function processTextChunk(
243	  ws: WebSocket,
244	  session: ChatSession,
245	  state: StreamState,
246	  parser: ThinkingTagParser,
247	  text: string
248	): void {
249	  const segments = parser.push(text);
250	  for (const segment of segments) {
251	    handleTextSegment(ws, session, state, segment);
252	  }
253	}
254	
255	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
256	  if (segment.type === 'thinking') {
257	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
258	    return;
259	  }
260	  commitAndClear(ws, session, state, 'thinkingIndex');
261	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
262	}
263	
264	function streamSegment(
265	  ws: WebSocket,
266	  session: ChatSession,
267	  state: StreamState,
268	  key: StateIndexKey,
269	  createEntry: EntryFactory,
270	  content: string
271	): void {
272	  const isNew = initSegment(session, state, key, createEntry);
273	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
274	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
275	  appendDelta(session, state[key]!, content);
276	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
277	}
278	
279	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
280	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
281	  markSuppressed(session, index);
282	  sendSkip(ws, index);
283	}
284	
285	function markSuppressed(session: ChatSession, index: number): void {
286	  const entry = session.entries[index];
287	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
288	}
289	
290	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
291	  if (state[key] !== null) return false;
292	  state[key] = appendEntry(session, createEntry());
293	  return true;
294	}
295	
296	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
297	  const index = state[key];
298	  if (index === null) return;
299	
300	  commitEntry(session, index);
301	  state[key] = null;
302	
303	  // Only what the client received can be retracted, and only assistant entries.
304	  if (state.suppressOutput) return;
305	
306	  sendCommit(ws, index);
307	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
308	}
309	
310	function processToolUseChunk(
311	  ws: WebSocket,
312	  session: ChatSession,
313	  toolCall: {name: string; input: Record<string, unknown>}
314	): void {
315	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
316	  const toolIndex = appendEntry(session, toolEntry);
317	  sendUpsert(ws, toolIndex, toolEntry);
318	}
319	
320	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
321	  for (const msg of clientMessages) {
322	    log.debug('stream', 'forwarding client message to frontend', {
323	      type: msg.type,
324	      index: 'index' in msg ? msg.index : undefined,
325	    });
326	    sendJson(ws, msg);
327	  }
328	}
329	
330	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
331	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
332	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
333	  commitOpenEntries(ws, session, state);
334	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
335	
336	  for (const idx of state.sentAssistantIndices) {
337	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
338	    markSuppressed(session, idx);
339	  }
340	
341	  state.sentAssistantIndices = [];
342	  state.suppressOutput = true;
343	}
344	
345	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
346	  flushHeldText(ws, session, state, parser);
347	  commitOpenEntries(ws, session, state);
348	}
349	
350	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
351	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
352	  for (const segment of parser.flush()) {
353	    handleTextSegment(ws, session, state, segment);
354	  }
355	}
356	
357	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
358	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
359	  const index = state[key];
360	  if (index === null) return;
361	  markTruncated(session, index);
362	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
363	  commitAndClear(ws, session, state, key);
364	}
365	
366	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
367	  commitAndClear(ws, session, state, 'thinkingIndex');
368	  commitAndClear(ws, session, state, 'assistantIndex');
369	}
370	
371	function handlePing(ws: WebSocket, timestamp: number): void {
372	  ws.send(JSON.stringify({type: 'pong', timestamp}));
373	}
