    let hops = 0;
    let everyHopCalled = true;
    let current = outer;
    while (current) {
        hops += 1;
        everyHopCalled = everyHopCalled && isCalled(current);
        const inner = unwrapToMember(current.object);
        if (!inner) {
            return { hops, everyHopCalled, root: rootOf(current.object) };
        }
        current = inner;
    }
    return { hops, everyHopCalled, root: null };
}
