    meta: {
        type: "suggestion",
        docs: {
            description: "Enforce a maximum member-access chain depth (Law of Demeter); fluent all-call chains, this, and well-known globals are exempt",
        },
        schema: [
            {
                type: "object",
                properties: {
                    max: { type: "integer", minimum: 1 },
                    allowRoots: { type: "array", items: { type: "string" } },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            chainTooDeep: "Member chain '{{chain}}' reaches {{depth}} hops deep (max {{max}}); ask the direct collaborator for what you need",
        },
    },
    create(context) {
        const options = context.options[0] ?? {};
        const max = options.max ?? DEFAULT_MAX;
        const allowedRoots = new Set([
            ...DEFAULT_ALLOWED_ROOTS,
            ...(options.allowRoots ?? []),
        ]);
        const sourceCode = context.sourceCode;
        return {
            MemberExpression(node) {
                if (continuesChain(node)) {
                    return;
                }
                const { hops, everyHopCalled, root } = measureChain(node);
                if (hops <= max || everyHopCalled || isExemptRoot(root, allowedRoots)) {
                    return;
                }
                context.report({
                    node,
                    messageId: "chainTooDeep",
                    data: reportData(node, hops, max, sourceCode),
                });
            },
        };
    },
};

