import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import type {SessionCursor} from '../../types/sessionStore.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a list_sessions limit and before cursor within the protocol and rejects a malformed one naming the field', () => {
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const accepted = [
      {frame: {type: 'list_sessions'}, data: {type: 'list_sessions'}},
      {frame: {type: 'list_sessions', limit: 0}, data: {type: 'list_sessions', limit: 0}},
      {
        frame: {type: 'list_sessions', limit: 10, before, userId: 'u2'},
        data: {type: 'list_sessions', limit: 10, before},
      },
      {
        frame: {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's1'}},
        data: {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's1'}},
      },
    ];
    for (const {frame, data} of accepted) {
      expect(validateMessage(frame)).toEqual({valid: true, data});
    }

    const bad = [
      {frame: {type: 'list_sessions', limit: 'ten'}, names: 'limit'},
      {frame: {type: 'list_sessions', limit: -1}, names: 'limit'},
      {frame: {type: 'list_sessions', limit: 1.5}, names: 'limit'},
      {frame: {type: 'list_sessions', before: 'not-an-object'}, names: 'before'},
      {
        frame: {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
        names: 'before sessionId',
      },
      {
        frame: {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
        names: 'before sessionId',
      },
      {frame: {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}, names: 'before updatedAt'},
      {frame: {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}, names: 'before updatedAt'},
    ];
    // The field a refusal names, read out of the `list_sessions <field> must be …` the validator answers with.
    const fieldNamed = (result: ValidationResult): string =>
      result.valid ? '' : result.error.replace('list_sessions ', '').split(' must be')[0];

    expect({
      accepted: accepted.map(({frame}) => validateMessage(frame)),
      refused: bad.map(({frame, names}) => {
        const result = validateMessage(frame);
        return {valid: result.valid, names, named: fieldNamed(result)};
      }),
    }).toEqual({
      accepted: accepted.map(({data}) => ({valid: true, data})),
      refused: bad.map(({names}) => ({valid: false, names, named: names})),
